<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {displayText,ruleVersionText,label,time} from '../api'
import {useSituation,typeNames} from '../situation'
import {metricValue,type EvidenceSnapshot} from '../evidence'
import DeviceAnalysisPanel from './DeviceAnalysisPanel.vue'
import Icon from './Icon.vue'
const emit=defineEmits<{'open-evidence':[snapshot:EvidenceSnapshot];'show-event':[id:string];'show-device':[id:string]}>()
const {data,loading,failure,refresh}=useSituation(),query=ref(''),selectedId=ref('')
const devices=computed(()=>data.value?.devices.filter(device=>`${device.code} ${device.name} ${typeNames[device.type]||device.type}`.includes(query.value))||[])
const selected=computed(()=>data.value?.devices.find(device=>device.id===selectedId.value))
onMounted(()=>void refresh())
</script>
<template><div class="device-center"><div class="module-header"><div><h2>设备与监测</h2><p>全域设备当前状态 · 与地图同源 · 关联事件核查使用独立证据快照</p></div><button class="outline-button" :disabled="loading" @click="refresh()"><Icon name="refresh" :size="15"/>刷新设备</button></div><div v-if="failure" class="evidence-error" role="alert">{{displayText(failure)}}</div><label class="execution-search"><Icon name="search" :size="16"/><input v-model="query" aria-label="搜索设备" placeholder="搜索设备编号、名称或类型"/></label><p v-if="loading&&!data" class="panel-hint">正在加载设备…</p><div class="device-grid"><button v-for="device in devices" :key="device.id" class="device-card" :class="{chosen:selectedId===device.id}" @click="selectedId=device.id"><div><span class="device-icon"><Icon name="device" :size="19"/></span><span class="status-badge" :class="device.status">{{label(device.status)}}</span></div><h3>{{device.code}}</h3><p>{{displayText(device.name)}}</p><small>{{typeNames[device.type]||device.type}}</small><span class="device-link">查看当前读数与关联事件 <Icon name="arrow" :size="14"/></span></button></div><p v-if="!loading&&!devices.length" class="panel-hint">没有符合条件的设备，请调整搜索或刷新数据。</p><section v-if="selected" class="detail-panel"><div class="section-caption"><span>{{selected.code}} · {{displayText(selected.name)}}</span><button class="icon-button" aria-label="关闭设备详情" @click="selectedId=''"><Icon name="close" :size="16"/></button></div><div class="execution-facts"><div><dt>设备类型</dt><dd>{{typeNames[selected.type]||selected.type}}</dd></div><div><dt>位置 / 楼层</dt><dd>{{displayText(data?.spaces.find(space=>space.id===selected?.building_id)?.name||'区域待核实')}} · {{displayText(selected.floor)}}</dd></div></div><div v-for="metric in selected.metrics" :key="metric.observation_id||metric.label" class="observation"><div><strong>{{displayText(metric.label)}}</strong><small>{{time(metric.observed_at,true)}} · {{label(metric.quality)}} · 当前设备状态</small></div><span>{{metricValue(metric)}}</span></div><div v-for="reference in selected.references||[]" :key="reference.rule_id" class="assessment-reference"><strong>{{displayText(reference.reference_label)}}</strong><p>{{displayText(reference.source_label)}} · {{ruleVersionText(reference.rule_version)}}</p></div><p v-if="!selected.references?.length" class="panel-hint">此设备尚无已配置的演示参考规则，不推断正常范围。</p><button class="outline-button" @click="emit('show-device',selected.id)"><Icon name="map" :size="15"/>地图定位设备</button><DeviceAnalysisPanel :device-id="selected.id" source-view="map" :image-id="selected.anchor?.image_id||null" @open-evidence="emit('open-evidence',$event)" @select-event="emit('show-event',$event)"/></section></div></template>
